import math

def most_similar(query, corpus):
    def cos(a, b):
        dot = sum(x * y for x, y in zip(a, b))
        na = math.sqrt(sum(x * x for x in a))
        nb = math.sqrt(sum(x * x for x in b))
        if na == 0 or nb == 0:
            return -1.0
        return dot / (na * nb)
    best_i, best = 0, -2.0
    for i, v in enumerate(corpus):
        s = cos(query, v)
        if s > best:
            best, best_i = s, i
    return best_i

